  };

  # --- ZRAM ---
  # CHANGED 2026-09-04: memoryPercent 150 -> 200 for work-over-fps.
  # Box was critical: 30G RAM + 45G zram both ~100% full (1.7G avail,
  # 284M swap free, 3.3x zstd ratio). +15G zram headroom; disk swap
  # below acts as overflow so OOM-killer doesn't fire during builds.
  # Previous: 2026-08-25 100 -> 150 after Aug 25 swap-thrash incident.
  zramSwap = {
    enable = true;
    algorithm = "zstd";
    memoryPercent = 200;
    priority = 5;
  };

  # --- SWAP ---
  # CHANGED 2026-09-26: 64G swapfile moved from / (nvme, ~91% full) to
  # /mnt/data (SATA, 349G free). Same overflow role behind zram (prio 5
  # fills first, disk prio 1 only after). NixOS auto-creates the file on
  # rebuild; systemd orders it after the /mnt/data mount, and the mount
  # itself is now boot-required (no `nofail`), which is the guarantee.
  # After the first reboot on this config: verify with `swapon -s`
  # (expect zram + partition + /mnt/data/swapfile), then `sudo rm /swapfile`
  # to reclaim 64G on the nvme. Until that reboot, this changes nothing.
  # (2026-09-04: file was /swapfile on nvme; the nvme partition entry stays.)
  swapDevices = lib.mkForce [
    {
      device = "/dev/disk/by-uuid/5021c67f-4e1f-4a52-94a4-52ca9325d4ef";
      priority = 1;
    }
    {
      device = "/mnt/data/swapfile";
      size = 65536;
      priority = 1;
    }
  ];

  # MEMORY PERFORMANCE TUNING (CHANGED 2026-08-25, zram-heavy workload).
  # The old values (swappiness=10, page-cluster default) were tuned for
  # DISK swap, not zram — they made the Aug 25 thrash worse:
  # - swappiness=10 forced the kernel to evict page cache / stall in direct
  #   reclaim instead of moving cold anon pages into compressed RAM (3.9x).
  # - page-cluster=3 means 8-page (32KiB) read bursts from swap; correct for
  #   NVMe swap, wasteful latency for zram random access. Must be 0.
  # - watermark_scale_factor=125 wakes kswapd earlier so reclaim happens in
  #   the background instead of stalling allocations at the low watermark.
  # - watermark_boost_factor=0 avoids extra synchronous reclaim bursts after
  #   fragmentation events (desktop/dev workload, no hugepage requirements).
  # CHANGED 2026-09-25: swappiness 150 -> 60. Permanently overcommitted box
  # (40 agents); 150 evicted hot anon pages into zram and faulted them right
  # back (kswapd ~37%, heavy swap churn). 60 keeps the working set resident;
  # zram still absorbs genuinely cold pages.
  boot.kernel.sysctl = {
    "vm.swappiness" = 60;              # resident working set over zram churn
    "vm.page-cluster" = 0;             # no readahead burst for zram (random access)
    "vm.watermark_scale_factor" = 125; # kswapd starts earlier, smoother under load
    "vm.watermark_boost_factor" = 0;   # no boost-driven reclaim stalls
    "vm.vfs_cache_pressure" = 75;      # unchanged: keep retaining dentry/inode cache
  };


  # --- POWER: sleep is fully disabled on this box. ---
  # History: PowerDevil auto-suspended despite IdleAction=ignore and
  # ~/.config/powerdevilrc autoSuspendIdleTimeoutSec=0 (it slept Aug 19/22 2026
  # overnight while long-running agent jobs were active). Config-level persuasion
  # does not stick, so sleep is now blocked at the systemd unit level: masking
  # these targets makes `systemctl suspend`, KDE Leave->Sleep, power-key sleep,
  # PowerDevil idle suspend — every path — fail outright.
  # To ever sleep again: remove this list and nixos-rebuild switch.
  systemd.suppressedSystemUnits = [
    "sleep.target"
    "suspend.target"
    "hibernate.target"
    "hybrid-sleep.target"
    "suspend-then-hibernate.target"

